#!/bin/sh
# Installs the newest hpy @CHANNEL@ release for this machine into
# /usr/local/bin.
#
# Generated by packaging/update-repo.sh from packaging/install-wrapper.sh,
# which fills in the channel and the URL this file is served from, and
# published as install.sh, install-beta.sh and install-alpha.sh.
#
# How it installs:
#   1. dist's installer for the release (hpy-cli-installer.sh) downloads hpy
#      and checks its checksum, unprivileged, into a temporary directory.
#   2. The binary is copied into /usr/local/bin with `install -m 0755`. That
#      copy (and creating /usr/local/bin when it is missing) is the only step
#      that can use sudo, and only when the directory is not writable by you.
#      sudo reads the password from the terminal, so `curl | sh` works.
#   3. The install receipt `hpy update` reads is written as you, never as root.
#   4. A copy an earlier version of this installer put in ~/.cargo/bin is
#      offered for removal: that one file, nothing else.
#
# Environment:
#   HPY_CLI_INSTALL_DIR    install into <dir>/bin instead, with no sudo: dist's
#                          installer on its own, as before. Also
#                          CARGO_DIST_FORCE_INSTALL_DIR, which dist reads too.
#   HPY_CLI_SYSTEM_DIR     FOR TESTING ONLY: a directory in place of
#                          /usr/local/bin (packaging/test-installer.sh).
#   HPY_CLI_INSTALLER_URL  FOR TESTING ONLY: where to download dist's installer
#                          from, in place of the release on GitHub.
#
# Everything runs from `main`, at the end, so nothing happens until the whole
# file has arrived through the pipe.
set -eu

channel=@CHANNEL@
pages=@BASE_URL@
repo=happyproto/cli
# 1 only in the copy packaging/test-installer.sh makes: the published scripts
# have 0, so HPY_CLI_SYSTEM_DIR and HPY_CLI_INSTALLER_URL do nothing there,
# and a variable left exported from testing can't move an install or fetch
# over plain HTTP.
test_knobs=@TEST_KNOBS@

say() {
  printf '%s\n' "$*" >&2
}

die() {
  printf 'hpy installer: %s\n' "$*" >&2
  exit 1
}

# sudo asks for a password on /dev/tty, not stdin, which is this script.
have_tty() {
  (: </dev/tty) 2>/dev/null
}

# Whether a directory can be written to, answered by writing to it.
writable() {
  [ -d "$1" ] || return 1
  probe=$(mktemp "$1/.hpy-probe.XXXXXXXXXX" 2>/dev/null) || return 1
  rm -f "$probe"
}

# A path's owner, by name (owner_name) or uid (owner_uid). `stat` takes
# different flags on macOS and Linux; `ls -ld` prints the same columns on both.
# shellcheck disable=SC2012
owner_name() {
  ls -ld "$1" | awk '{print $3}'
}
# shellcheck disable=SC2012
owner_uid() {
  ls -ldn "$1" | awk '{print $3}'
}

# Two paths name the same directory.
same_dir() {
  a=$(cd -P -- "$1" 2>/dev/null && pwd) || return 1
  b=$(cd -P -- "$2" 2>/dev/null && pwd) || return 1
  [ -n "$a" ] && [ "$a" = "$b" ]
}

# This script's own URL, for the commands it prints.
self_url() {
  if [ "$channel" = stable ]; then
    printf '%s/install.sh' "$pages"
  else
    printf '%s/install-%s.sh' "$pages" "$channel"
  fi
}

installer_url() {
  if [ "$test_knobs" = 1 ] && [ -n "${HPY_CLI_INSTALLER_URL:-}" ]; then
    printf '%s' "$HPY_CLI_INSTALLER_URL"
  elif [ "$channel" = stable ]; then
    printf '%s' "https://github.com/$repo/releases/latest/download/hpy-cli-installer.sh"
  else
    # GitHub's `releases/latest` is the newest stable release and never a
    # prerelease, so this reads the releases list, which the API answers
    # newest first, and takes the first tag on this channel.
    tag=$(curl --proto '=https' --tlsv1.2 -fsSL \
      "https://api.github.com/repos/$repo/releases?per_page=100" \
      | sed -n 's/.*"tag_name"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' \
      | grep -E -- '-@CHANNEL@(\.|$)' \
      | head -n 1)
    case "$tag" in
      "") die "no hpy release on the $channel channel" ;;
      v*[!A-Za-z0-9.+-]*) die "unexpected release tag: $tag" ;;
      v*) ;;
      *) die "unexpected release tag: $tag" ;;
    esac
    printf '%s' "https://github.com/$repo/releases/download/$tag/hpy-cli-installer.sh"
  fi
}

download() { # url file
  if [ "$test_knobs" = 1 ] && [ -n "${HPY_CLI_INSTALLER_URL:-}" ]; then
    curl -fsSL "$1" -o "$2"
  else
    curl --proto '=https' --tlsv1.2 -fsSL "$1" -o "$2"
  fi
}

# The receipt dist's installer writes, filled in for the flat layout in
# $sysdir. An unmanaged install (the staging run) writes none, so this starts
# from the template in dist's installer itself, which keeps the shape the same
# as the one dist writes; a template that cannot be filled in falls back to
# that shape written out here.
receipt_json() { # installer version
  json=$(sed -n '/^{"binaries":/{p;q;}' "$1" \
    | sed -e 's/"CARGO_DIST_BINS"/"hpy"/' \
      -e 's/"CARGO_DIST_DYLIBS"//' \
      -e 's/"CARGO_DIST_STATICLIBS"//' \
      -e "s,AXO_INSTALL_PREFIX,$sysdir," \
      -e 's/"install_layout":"unspecified"/"install_layout":"flat"/' \
      -e 's/"modify_path":true/"modify_path":false/')
  case "$json" in
    *CARGO_DIST_* | *AXO_* | *unspecified* | "")
      json='{"binaries":["hpy"],"binary_aliases":{},"cdylibs":[],"cstaticlibs":[],"install_layout":"flat","install_prefix":"'"$sysdir"'","modify_path":false,"provider":{"source":"cargo-dist","version":"0.32.0"},"source":{"app_name":"hpy-cli","name":"cli","owner":"happyproto","release_type":"github"},"version":"'"$2"'"}'
      ;;
  esac
  printf '%s\n' "$json"
}

no_sudo() {
  say ""
  say "hpy is downloaded, but could not be copied into $sysdir: $1"
  say "To install it there, run this from a terminal, where sudo can ask for your password:"
  say ""
  say "  curl -fsSL $(self_url) | sh"
  say ""
  say "Or install it without sudo, into ~/.local/bin:"
  say ""
  say "  curl -fsSL $(self_url) | HPY_CLI_INSTALL_DIR=\"\$HOME/.local\" sh"
  exit 1
}

main() {
  sysdir=/usr/local/bin
  if [ "$test_knobs" = 1 ]; then
    sysdir=${HPY_CLI_SYSTEM_DIR:-/usr/local/bin}
  fi
  case "$sysdir" in
    /*) ;;
    *) die "HPY_CLI_SYSTEM_DIR must be an absolute path" ;;
  esac
  # Kept to characters that need no quoting, so the receipt (JSON) and the
  # commands printed here can hold the path as it is.
  case "$sysdir" in
    *[!A-Za-z0-9/._+-]*) die "$sysdir: the install directory may hold only letters, digits and / . _ + -" ;;
  esac
  sysdir=${sysdir%/}
  [ -n "$sysdir" ] || die "the install directory cannot be /"
  dest="$sysdir/hpy"

  tmp=$(mktemp -d "${TMPDIR:-/tmp}/hpy-install.XXXXXXXXXX") \
    || die "could not create a temporary directory"
  trap 'rm -rf "$tmp"' EXIT
  trap 'exit 129' HUP
  trap 'exit 130' INT
  trap 'exit 143' TERM

  url=$(installer_url)
  download "$url" "$tmp/installer.sh" </dev/null || die "could not download $url"

  # The override: dist's installer on its own, exactly as before this
  # script copied anything anywhere. No sudo.
  if [ -n "${HPY_CLI_INSTALL_DIR:-}" ] || [ -n "${CARGO_DIST_FORCE_INSTALL_DIR:-}" ]; then
    sh "$tmp/installer.sh" "$@" </dev/null
    return
  fi

  uid=$(id -u)
  user=$(id -un 2>/dev/null || echo "uid $uid")
  if [ "$uid" = 0 ]; then
    say "Running as root, so installing into $sysdir without sudo."
    if [ -n "${SUDO_USER:-}" ]; then
      say "(There is no need to run this with sudo: run as yourself, it uses sudo only to copy hpy into $sysdir.)"
    fi
  fi

  version=$(sed -n 's/^APP_VERSION="\([0-9A-Za-z.+-]*\)"$/\1/p' "$tmp/installer.sh" | head -n 1)
  [ -n "$version" ] || die "$url does not look like hpy's installer"

  # 1. Download and verify, unprivileged, into the temporary directory. An
  # unmanaged install is flat (<dir>/hpy), edits no shell profile and writes
  # no receipt.
  say "Downloading hpy ${version}..."
  # Its output ("installing to /tmp/...") is shown only if it fails.
  if ! HPY_CLI_UNMANAGED_INSTALL="$tmp/stage" HPY_CLI_NO_MODIFY_PATH=1 \
    sh "$tmp/installer.sh" "$@" </dev/null >"$tmp/installer.log" 2>&1; then
    cat "$tmp/installer.log" >&2
    die "dist's installer failed"
  fi
  staged="$tmp/stage/hpy"
  if [ ! -f "$staged" ] || [ -L "$staged" ]; then
    die "dist's installer did not leave hpy in $tmp/stage"
  fi

  # 2. Copy it into place.
  if [ -L "$dest" ]; then
    die "$dest is a symbolic link (Homebrew's, perhaps), so it was left alone. Upgrade hpy with whatever put it there, or remove it and run this again."
  fi
  if [ -d "$dest" ]; then
    die "$dest is a directory"
  fi
  if [ "$uid" = 0 ]; then
    mkdir -p "$sysdir"
    install -m 0755 "$staged" "$dest"
  else
    if [ ! -d "$sysdir" ]; then
      mkdir -p "$sysdir" 2>/dev/null || true
    fi
    if writable "$sysdir"; then
      install -m 0755 "$staged" "$dest"
    else
      command -v sudo >/dev/null 2>&1 || no_sudo "it is not writable by $user, and sudo is not installed."
      if [ -d "$sysdir" ]; then
        mkdir_first=0
        owner=$(owner_name "$sysdir")
        if [ "$owner" != "$user" ]; then
          why="$sysdir is owned by $owner"
        else
          why="$sysdir is not writable by $user"
        fi
        what="to copy hpy there"
      else
        mkdir_first=1
        why="$sysdir does not exist and only root can create it"
        what="to create it and copy hpy there"
      fi
      if have_tty; then
        say "$why, so sudo will ask for your password once $what."
        if [ "$mkdir_first" = 1 ]; then
          sudo mkdir -p "$sysdir" </dev/null || no_sudo "sudo mkdir -p $sysdir failed."
        fi
        sudo install -m 0755 "$staged" "$dest" </dev/null \
          || no_sudo "sudo install failed."
      else
        say "$why, and with no terminal sudo cannot ask for a password, so trying sudo -n $what."
        if [ "$mkdir_first" = 1 ]; then
          sudo -n mkdir -p "$sysdir" </dev/null || no_sudo "sudo -n needs a password, and there is no terminal to ask for it."
        fi
        sudo -n install -m 0755 "$staged" "$dest" </dev/null \
          || no_sudo "sudo -n needs a password, and there is no terminal to ask for it."
      fi
    fi
  fi
  cmp -s "$staged" "$dest" || die "$dest is not the binary that was downloaded"
  say "Installed hpy $version to $dest."

  # 3. The receipt, as this user. As root it is written only into root's own
  # home: a receipt written as root into someone else's would be one they
  # cannot replace.
  owns_home=1
  if [ -z "${HOME:-}" ]; then
    owns_home=0
    say "HOME is not set, so hpy's install receipt was not written, and \`hpy update\` will not replace this copy itself; run this installer again to update it."
  elif [ "$uid" = 0 ]; then
    config="${XDG_CONFIG_HOME:-${HOME:-/}}"
    if [ ! -d "${HOME:-}" ] || [ "$(owner_uid "$HOME")" != 0 ] \
      || { [ -d "$config" ] && [ "$(owner_uid "$config")" != 0 ]; }; then
      owns_home=0
      say "Not writing hpy's install receipt as root into ${HOME:-an unset HOME}, which is not root's own, so \`hpy update\` will not replace this copy itself; run this installer again (as yourself) to update it."
    fi
  fi
  old_prefix=""
  if [ "$owns_home" = 1 ]; then
    receipt_home="${XDG_CONFIG_HOME:-$HOME/.config}/hpy-cli"
    receipt="$receipt_home/hpy-cli-receipt.json"
    if [ -f "$receipt" ]; then
      old_prefix=$(sed -n 's/.*"install_prefix":"\([^"]*\)".*/\1/p' "$receipt" | head -n 1)
    fi
    if mkdir -p "$receipt_home" 2>/dev/null \
      && receipt_json "$tmp/installer.sh" "$version" >"$receipt.tmp" 2>/dev/null \
      && mv -f "$receipt.tmp" "$receipt"; then
      :
    else
      rm -f "$receipt.tmp" 2>/dev/null || true
      say "warning: could not write $receipt, so \`hpy update\` will not recognise this copy. Run this installer again to update it."
    fi
  fi

  # 4. The copy an earlier version of this installer put in ~/.cargo/bin.
  # It counts as the installer's only when the receipt (read before it was
  # replaced above) names that cargo home; otherwise `cargo install` built it,
  # and it is cargo's to remove.
  if [ "$owns_home" = 1 ]; then
    cargo_home="${CARGO_HOME:-$HOME/.cargo}"
    old="$cargo_home/bin/hpy"
    shown=$old
    case "$old" in
      "$HOME"/*) shown="~${old#"$HOME"}" ;;
    esac
    # Compared as directories, not strings: $sysdir spelled another way, or
    # a cargo home reached through a symlink, can name the copy just
    # installed, which must never be offered for removal.
    if ! same_dir "$(dirname "$old")" "$sysdir" && { [ -e "$old" ] || [ -L "$old" ]; }; then
      if [ -n "$old_prefix" ] && same_dir "$old_prefix" "$cargo_home" \
        && [ -f "$old" ] && [ ! -L "$old" ]; then
        if have_tty; then
          printf 'Remove the old copy in %s? [Y/n] ' "$shown" >/dev/tty
          answer=n
          read -r answer </dev/tty || answer=n
          case "$answer" in
            "" | [Yy] | [Yy][Ee][Ss])
              # That one file, and only while it is still a plain file.
              if [ -f "$old" ] && [ ! -L "$old" ] && rm -f -- "$old"; then
                say "Removed $shown."
              else
                say "warning: could not remove $shown."
              fi
              ;;
            *) say "Kept $shown. To remove it later: rm $old" ;;
          esac
        else
          say "The copy of hpy in $shown is from an earlier install and is no longer needed. To remove it:"
          say ""
          say "  rm $old"
          say ""
        fi
      else
        say "$shown was not put there by this installer (cargo install, perhaps), so it was left alone. If $(dirname "$old") comes before $sysdir on your PATH, it shadows the new copy; \`cargo uninstall hpy-cli\` removes it."
      fi
    fi
  fi

  found=$(command -v hpy 2>/dev/null || true)
  if [ -z "$found" ]; then
    say "warning: $sysdir is not on your PATH, so \`hpy\` will not be found until it is."
  elif [ "$found" != "$dest" ]; then
    say "warning: \`hpy\` runs $found, which comes before $sysdir on your PATH, not the copy just installed."
  fi
}

main "$@"
